  private Track SelectedTrack{get{return _selectedTrackId.HasValue?FindTrack(_selectedTrackId.Value):null;}}
  private Region SelectedRegion{get{var t=SelectedTrack;return t!=null&&_selectedRegionId.HasValue?FindRegion(t,_selectedRegionId.Value):null;}}
  private void CommitEditorNotes(List<MidiNote> notes){var t=SelectedTrack;var r=SelectedRegion;if(t==null||r==null)return;_history.Execute(_project,new SetMidiNotesCommand(_project,t.Id,r.Id,notes));RefreshState();}
  private void CommitStudio(string description,StudioState state){_history.Execute(_project,new SetStudioCommand(description,_project.Studio,state));RefreshState();}
  private void RefreshAdvancedFeatures(){if(_launcher==null)return;_launcher.SetContent(_project,_engine);var t=SelectedTrack;var r=SelectedRegion;_score.SetContent(t,r,_project.TimeSignatureNumerator);_steps.SetContent(t,r);_automation.SetContent(_project,_selectedTrackId);_comp.SetContent(_project,t);_pitch.SetContent(t,r,_project.Tempo);}
  private bool ExecuteAdvanced(AppCommand command){
   switch(command){
   case AppCommand.ToggleLauncher:if(_sessionSplit.Panel1Collapsed)ShowSession(1);else ShowSession(0);break;
   case AppCommand.LauncherOnly:ShowSession(1);break;case AppCommand.TracksOnly:ShowSession(0);break;case AppCommand.LauncherBoth:ShowSession(2);break;
   case AppCommand.ShowScore:EnsureMidiRegion();ShowLower(_score);break;case AppCommand.ShowSteps:EnsureMidiRegion();ShowLower(_steps);break;case AppCommand.ShowAutomation:ShowLower(_automation);break;case AppCommand.ShowComp:ShowLower(_comp);break;case AppCommand.ShowPitch:ShowLower(_pitch);break;
   case AppCommand.ShowSamples:if(!_mediaSplit.Panel2Collapsed&&_samples.Visible){_mediaSplit.Panel2Collapsed=true;}else{_mediaSplit.Panel2.Controls.Clear();_mediaSplit.Panel2.Controls.Add(_samples);_mediaSplit.Panel2Collapsed=false;_mediaSplit.SplitterDistance=Math.Max(_mediaSplit.Panel1MinSize,_mediaSplit.Width-375);}break;
   case AppCommand.ExportAudio:try{_engine.CapturePluginStates();using(var export=new AudioExportDialog(_project))export.ShowDialog(this);}catch(Exception ex){ShowError("Master export failed",ex);}break;
   case AppCommand.InputRouting:ShowInputRouting();break;case AppCommand.QuickStart:ShowQuickStart();break;case AppCommand.SandboxStatus:ShowSandboxStatus();break;case AppCommand.ReturnArrangement:_engine.ReturnToArrangement();break;
   case AppCommand.ImportExchange:ImportExchange();break;case AppCommand.ExportExchange:ExportExchange();break;case AppCommand.ExportMidi:ExportMidi();break;default:return false;
   }return true;
  }
  private void CreateLauncherTemplate(){
   if(!ConfirmDiscardChanges())return;StopAudio();_engine.ResetProject();var p=new ProjectDocument{Name="Slop Session",Tempo=110};string[] names={"Rhythm","Pulse Bass","Electric Chords","Orbit Pluck"},sounds={"Drum Kit","Sub Bass","Classic Electric Piano","Pluck"};int[] colors={1,4,0,3};
   for(int i=0;i<4;i++){var t=ProjectFactory.CreateTrack(names[i],TrackType.Midi);t.Instrument=sounds[i];t.ColorIndex=colors[i];t.GainDb=i==0?-4:-9;for(int scene=0;scene<8;scene++){var r=ProjectFactory.CreateRegion(names[i]+" "+(scene+1),scene*4,4);if(i==0){for(int step=0;step<16;step++){if(step%4==0)r.Notes.Add(new MidiNote{StartBeat=step*.25,LengthBeats=.15,Pitch=36,Velocity=100});if(step%8==4)r.Notes.Add(new MidiNote{StartBeat=step*.25,LengthBeats=.15,Pitch=38,Velocity=85});if(step%2==0)r.Notes.Add(new MidiNote{StartBeat=step*.25,LengthBeats=.1,Pitch=42,Velocity=64+(step%4)*4});}}else if(i==1){foreach(int step in new[]{0,3,6,10,12})r.Notes.Add(new MidiNote{StartBeat=step*.25,LengthBeats=.4,Pitch=36+new[]{0,5,7,3}[scene%4],Velocity=95});}else if(i==2){foreach(int key in new[]{60,63,67})r.Notes.Add(new MidiNote{StartBeat=0,LengthBeats=3.75,Pitch=key+new[]{0,5,7,3}[scene%4],Velocity=78});}else{for(int step=0;step<8;step++)r.Notes.Add(new MidiNote{StartBeat=step*.5,LengthBeats=.3,Pitch=new[]{72,75,79,82}[step%4]+(scene%2)*-2,Velocity=74+step%3*5});}t.Regions.Add(r);p.Studio.Cells.Add(new LauncherCell{TrackId=t.Id,Scene=scene,RegionId=r.Id});}p.Tracks.Add(t);}
   _project=p;_projectPath=null;_history.Reset(false);_selectedTrackId=p.Tracks[0].Id;_selectedRegionId=p.Tracks[0].Regions[0].Id;RefreshState();
  }
  private void EnsureMidiRegion(){if(SelectedTrack==null||SelectedTrack.Type!=TrackType.Midi)return;if(SelectedRegion==null)AddRegion();}
  private void ShowLower(Control editor){if(!_workspaceSplit.Panel2Collapsed&&_lowerDock.ShowsEditor(editor)){_workspaceSplit.Panel2Collapsed=true;return;}RefreshAdvancedFeatures();_workspaceSplit.Panel2Collapsed=false;_lowerDock.ShowEditor(editor);editor.Focus();UpdateViewMenuChecks();}
  private void ShowSession(int mode){_sessionSplit.Panel1Collapsed=mode==0;_sessionSplit.Panel2Collapsed=mode==1;if(mode==2)_sessionSplit.SplitterDistance=Math.Max(300,Math.Min(_sessionSplit.Width-223,(int)(_sessionSplit.Width*.65)));_timeline.SetSessionHeaders(mode==2);_timeline.SetLaneHeight(_launcher.RowHeight);_launcher.Focus();}
  private void StartAdvancedFeatures(){
   if(!String.IsNullOrEmpty(StartupProjectPath))OpenProjectPath(StartupProjectPath);
   if(!_smokeMode){_recovery=new RecoveryStore(Path.GetDirectoryName(SettingsStore.DefaultPath));RestartIntegrations();}
   _advancedTimer.Start();
   if(McpMode){var server=new McpServer(delegate(string name,IDictionary<string,object> arguments){return Invoke((Func<object>)delegate{return McpDispatch(name,arguments);});});new Thread(delegate(){try{server.Run(Console.OpenStandardInput(),Console.OpenStandardOutput());}catch(Exception ex){try{Console.Error.WriteLine(ex.Message);}catch{}}}){IsBackground=true,Name="MCP stdio"}.Start();}
   else if(!_smokeMode&&_settings.Integration.QuickStart&&String.IsNullOrEmpty(StartupProjectPath))BeginInvoke((Action)ShowQuickStart);
  }
  private void RestartIntegrations(){
   if(_osc!=null){_osc.Dispose();_osc=null;}if(_link!=null){_link.Dispose();_link=null;}if(_launchpad!=null){_launchpad.Dispose();_launchpad=null;}
   try{if(_settings.Integration.OscEnabled){_osc=new OscConnection(_settings.Integration);_osc.Message+=delegate(OscMessage message){if(!IsDisposed)BeginInvoke((Action)delegate{try{if(message.Address=="/slop/play"||message.Address=="/avatar/parameters/SlopPlay"){bool play=message.Arguments.Length==0||Convert.ToBoolean(message.Arguments[0]);if(play&&!_engine.Playing)StartTransport();else if(!play&&_engine.Playing)StopAudio();}else if(message.Address=="/slop/stop")StopAudio();else if(message.Address=="/slop/tempo"&&message.Arguments.Length>0)SetTempo(Convert.ToDouble(message.Arguments[0]));else if(message.Address=="/slop/scene"&&message.Arguments.Length>0){int scene=Convert.ToInt32(message.Arguments[0]);foreach(var cell in _project.Studio.Cells)if(cell.Scene==scene)_engine.Launch(cell.TrackId,cell.RegionId,_project.TimeSignatureNumerator);if(!_engine.Playing)StartTransport();}}catch(Exception ex){_statusLabel.Text="OSC: "+ex.Message;}});};_osc.Failed+=delegate(Exception ex){OnEngineFailure(ex);};}if(_settings.Integration.LinkEnabled){_link=new LinkCompanion();_link.Commit(_project.Tempo,_engine.Playing);_lastLinkTempo=_project.Tempo;_lastLinkPlaying=_engine.Playing;}}catch(Exception ex){_statusLabel.Text=ex.Message;}
   if(_settings.Integration.LaunchpadEnabled)try{StartLaunchpad();}catch(Exception ex){_statusLabel.Text="Launchpad: "+ex.Message;}
  }
  private void StartLaunchpad(){
   var c=_settings.Integration;var input=WinMmDevices.MidiInputs().FirstOrDefault(d=>d.Id==c.LaunchpadInput&&d.Name==c.LaunchpadInputName);var output=WinMmDevices.MidiOutputs().FirstOrDefault(d=>d.Id==c.LaunchpadOutput&&d.Name==c.LaunchpadOutputName);
   if(input==null||output==null)throw new InvalidOperationException("Launchpad MIDI ports changed or are unavailable; select them again in Settings.");
   var controller=new LaunchpadController(input.Id,output.Id);_launchpad=controller;controller.Pad+=delegate(int status,int note,int velocity){if(IsDisposed||!IsHandleCreated)return;try{BeginInvoke((Action)delegate{if(IsDisposed||_launchpad!=controller)return;try{var cell=LaunchpadMapping.Cell(_project,status,note,velocity);if(cell==null)return;if(!_engine.Playing)StartTransport();if(!_engine.Playing)return;double bar=_project.TimeSignatureNumerator*4.0/_project.TimeSignatureDenominator;_engine.Launch(cell.TrackId,cell.RegionId,bar);_launcher.Invalidate();}catch(Exception ex){_statusLabel.Text="Launchpad: "+ex.Message;}});}catch(InvalidOperationException){}};
   try{controller.Update(_project,_engine);}catch{_launchpad=null;controller.Dispose();throw;}
  }
  private void AdvancedTick(object sender,EventArgs e){
   if(_recording&&_multiCapture!=null&&_multiCapture.Error!=null){StopAudio();return;}if(_launcher!=null&&_launcher.Visible)_launcher.Invalidate();if(_launchpad!=null)try{_launchpad.Update(_project,_engine);}catch(Exception ex){_statusLabel.Text="Launchpad: "+ex.Message;_launchpad.Dispose();_launchpad=null;}
   if(_recovery!=null&&DateTime.UtcNow>=_nextRecovery){_nextRecovery=DateTime.UtcNow.AddSeconds(_settings.Integration.RecoverySeconds);if(_history.IsDirty)try{var snapshot=ProjectFactory.Clone(_project);if(_multiCapture!=null)foreach(var take in _multiCapture.PendingTakes()){Track track=snapshot.Tracks.Find(t=>t.Id==take.TrackId);if(track!=null)track.Regions.Add(new Region{Id=take.RegionId,Name="Recovered recording",StartBeat=_recordStartBeat,LengthBeats=Math.Max(.25,take.Frames/(double)_settings.SampleRate*_project.Tempo/60),MediaPath=take.Path});}_recovery.Snapshot(snapshot,_projectPath);}catch(Exception ex){_statusLabel.Text="Recovery: "+ex.Message;}}
   if(_osc!=null)try{_osc.Send("/avatar/parameters/SlopPlaying",_engine.Playing);_osc.Send("/avatar/parameters/SlopBeat",(float)(_cursorBeat%4/4));_osc.Send("/avatar/parameters/SlopLevel",_engine.MasterPeak);}catch(Exception ex){_statusLabel.Text="OSC: "+ex.Message;}
   if(_link!=null){try{double tempo=_link.Tempo;bool playing=_link.Playing;if(Math.Abs(_project.Tempo-_lastLinkTempo)>.01||_engine.Playing!=_lastLinkPlaying){_link.Commit(_project.Tempo,_engine.Playing);_lastLinkTempo=_project.Tempo;_lastLinkPlaying=_engine.Playing;}else{if(tempo>=20&&tempo<=400&&Math.Abs(tempo-_lastLinkTempo)>.01){SetTempo(tempo);_lastLinkTempo=tempo;}if(playing!=_lastLinkPlaying){if(playing)StartTransport();else StopAudio();_lastLinkPlaying=playing;}}}catch(Exception ex){_statusLabel.Text="Link: "+ex.Message;_link.Dispose();_link=null;}}
  }
  private void DisposeAdvancedFeatures(){if(_wheelFilter!=null){Application.RemoveMessageFilter(_wheelFilter);_wheelFilter=null;}DisposeV7Features();if(_advancedTimer!=null){_advancedTimer.Stop();_advancedTimer.Dispose();}if(_osc!=null)_osc.Dispose();if(_link!=null)_link.Dispose();if(_launchpad!=null){_launchpad.Dispose();_launchpad=null;}if(_recovery!=null)_recovery.Close();WaveAudio.Stop();}
  private void ShowQuickStart(){
   using(var chooser=new QuickStartForm(RecoveryStore.Find(Path.GetDirectoryName(SettingsStore.DefaultPath)),_lastProject)){if(chooser.ShowDialog(this)!=DialogResult.OK)return;switch(chooser.ActionName){case "new":NewProject();break;case "launcher":CreateLauncherTemplate();ShowSession(1);break;case "open":OpenProject();break;case "example":OpenProjectPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Examples","First Light","First Light.slopdaw"));break;case "melodic":OpenProjectPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Examples","EDM Sample - Melodic House.slopdaw"));break;case "jpop":OpenProjectPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Examples","J-Pop - Shibuya.slopdaw"));break;case "settings":OpenPreferences();break;case "recover":if(ConfirmDiscardChanges()){_engine.ResetProject();_project=ProjectFile.Load(chooser.ProjectPath);_projectPath=null;_history.Reset(false);_selectedTrackId=_project.Tracks.Count>0?(Guid?)_project.Tracks[0].Id:null;_selectedRegionId=null;RefreshState();}break;}}
  }
  private void ShowInputRouting(){
   var t=SelectedTrack;if(t==null||t.Type!=TrackType.Audio){MessageBox.Show(this,"Select an audio track first.","Input Routing");return;}
   using(var dialog=new Form{Text=t.Name+" — Input Routing",ClientSize=new Size(420,195),StartPosition=FormStartPosition.CenterParent,BackColor=Color.FromArgb(60,60,61),ForeColor=Color.Gainsboro}){var route=_project.Studio.Route(t.Id);var channel=new NumericUpDown{Left=215,Top=18,Width=160,Minimum=1,Maximum=32,Value=route.Channel+1};var stereo=new CheckBox{Left=215,Top=57,Width=170,Text="Stereo pair",Checked=route.Channels==2};var monitor=new CheckBox{Left=215,Top=90,Width=180,Text="Input monitoring",Checked=route.Monitor};dialog.Controls.Add(new Label{Text="First input channel (1-based)",Left=15,Top=21,Width=195});dialog.Controls.Add(new Label{Text=_engine.InputChannels+" channels currently available",Left=15,Top=60,Width=195});dialog.Controls.Add(channel);dialog.Controls.Add(stereo);dialog.Controls.Add(monitor);var apply=new Button{Text="Apply",Left=280,Top=145,Width=95,DialogResult=DialogResult.OK};dialog.Controls.Add(apply);dialog.AcceptButton=apply;if(dialog.ShowDialog(this)==DialogResult.OK){var after=_project.Studio.Copy();after.Inputs.RemoveAll(r=>r.TrackId==t.Id);var selected=new InputRoute{TrackId=t.Id,Channel=(int)channel.Value-1,Channels=stereo.Checked?2:1,Monitor=monitor.Checked};if(selected.Channel+selected.Channels>Math.Max(1,_engine.InputChannels)){MessageBox.Show(this,"That input channel is unavailable on the current device.","Input Routing");return;}after.Inputs.Add(selected);CommitStudio("Change audio input route",after);}}
  }
  private void ShowSandboxStatus(){
   using(var dialog=new Form{Text="Plug-in Processes — per-instance isolation",ClientSize=new Size(760,330),BackColor=Color.FromArgb(56,56,56),ForeColor=Color.Gainsboro,StartPosition=FormStartPosition.CenterParent}){var list=new ListView{Dock=DockStyle.Fill,View=View.Details,FullRowSelect=true,BackColor=Color.FromArgb(42,42,42),ForeColor=Color.Gainsboro};list.Columns.Add("Track / Plug-in",300);list.Columns.Add("PID",80);list.Columns.Add("State",170);list.Columns.Add("Latency",90);foreach(var t in _project.Tracks)foreach(var slot in t.Plugins){var p=_engine.GetPlugin(slot.Id);list.Items.Add(new ListViewItem(new[]{t.Name+" / "+slot.Name,p==null?"—":p.WorkerId.ToString(),slot.Bypassed?"Bypassed":p==null?"Unavailable":p.Healthy?"Running":"Failed",p==null?"—":p.LatencySamples+" samples"}){Tag=slot.Id});}var restart=new Button{Text="Restart selected plug-in",Dock=DockStyle.Bottom,Height=32,FlatStyle=FlatStyle.Flat};restart.Click+=delegate{if(list.SelectedItems.Count==0)return;Guid id=(Guid)list.SelectedItems[0].Tag;var p=_engine.GetPlugin(id);if(p!=null)p.Dispose();_engine.RestartPlugin(id);_audioDeviceError=null;RefreshState();dialog.Close();};dialog.Controls.Add(list);dialog.Controls.Add(restart);dialog.ShowDialog(this);}
  }
  private void ImportExchange(){using(var d=new OpenFileDialog{Filter="Projects and MIDI|*.mid;*.midi;*.als;*.flp;*.dawproject|Standard MIDI File|*.mid;*.midi|FL Studio Project|*.flp|Ableton Live Set|*.als|DAWproject|*.dawproject"})if(d.ShowDialog(this)==DialogResult.OK)OpenExchangePath(d.FileName);}
  private async void OpenExchangePath(string file){if(_importing||_recording||!ConfirmDiscardChanges())return;_importing=true;try{var imported=await System.Threading.Tasks.Task.Factory.StartNew(()=>ProjectExchange.Import(file,Path.Combine(Path.GetDirectoryName(SettingsStore.DefaultPath),"Imported Media",Guid.NewGuid().ToString("N"))));await new UiDispatch(this);ClosePluginEditors();StopAudio();_engine.ResetProject();_project=imported.Project;_project.Studio.ImportNotes=String.Join(Environment.NewLine,imported.Warnings.Distinct().ToArray());_projectPath=null;_history.Reset(false);_cursorBeat=0;_selectedTrackId=_project.Tracks.Count==0?(Guid?)null:_project.Tracks[0].Id;_selectedRegionId=_project.Tracks.SelectMany(t=>t.Regions).Select(r=>(Guid?)r.Id).FirstOrDefault();RefreshState();}catch(Exception ex){ShowError("Project import failed",ex);}finally{_importing=false;}}
  private void ExportExchange(){using(var d=new SaveFileDialog{Filter="DAWproject|*.dawproject",FileName=SafeFileName(_project.Name)+".dawproject"})if(d.ShowDialog(this)==DialogResult.OK)try{_engine.CapturePluginStates();var warnings=ProjectExchange.ExportDawProject(_project,d.FileName);MessageBox.Show(this,"DAWproject saved."+Environment.NewLine+String.Join(Environment.NewLine,warnings.ToArray()),"Export report");}catch(Exception ex){ShowError("DAWproject export failed",ex);}}
  private void ExportMidi(){using(var dialog=new SaveFileDialog{Filter="Standard MIDI File|*.mid",FileName=SafeFileName(_project.Name)+".mid"})if(dialog.ShowDialog(this)==DialogResult.OK)try{MidiFileExport.Save(_project,dialog.FileName);_statusLabel.Text=UiText.Translate("MIDI file exported")+": "+dialog.FileName;}catch(Exception ex){ShowError("MIDI export failed",ex);}}
  private static double Arg(IDictionary<string,object> args,string key,double fallback){return args.ContainsKey(key)?Convert.ToDouble(args[key],System.Globalization.CultureInfo.InvariantCulture):fallback;}
  private object McpDispatch(string name,IDictionary<string,object> args){
   AuthorizeMcpRequest(name,args);
   switch(name){
   case "get_project":return new {project=new JavaScriptSerializer().DeserializeObject(ProjectFile.Serialize(_project)),position=_engine.PositionBeat,playing=_engine.Playing,inputChannels=_engine.InputChannels,pdcSamples=_engine.CompensationSamples};
   case "create_track":var type=args.ContainsKey("type")&&Convert.ToString(args["type"])=="audio"?TrackType.Audio:TrackType.Midi;var track=ProjectFactory.CreateTrack(args.ContainsKey("name")?Convert.ToString(args["name"]):"AI Track",type);_history.Execute(_project,new AddTrackCommand(track,_project.Tracks.Count));Select(track.Id,null);return new {trackId=track.Id};
   case "add_midi_note":var t=FindTrack(Guid.Parse(Convert.ToString(args["trackId"])));if(t==null||t.Type!=TrackType.Midi)throw new InvalidOperationException("MIDI track required.");Region r=args.ContainsKey("regionId")?FindRegion(t,Guid.Parse(Convert.ToString(args["regionId"]))):null;if(r==null){r=ProjectFactory.CreateRegion("MIDI",0,Math.Max(4,Math.Ceiling(Arg(args,"start",0)+Arg(args,"duration",1))));_history.Execute(_project,new AddRegionCommand(t.Id,r,t.Regions.Count));}var notes=ProjectFactory.CloneNotes(r.Notes);notes.Add(new MidiNote{StartBeat=Arg(args,"start",0),LengthBeats=Arg(args,"duration",1),Pitch=(int)Arg(args,"pitch",60),Velocity=(int)Arg(args,"velocity",100)});_history.Execute(_project,new SetMidiNotesCommand(_project,t.Id,r.Id,notes));Select(t.Id,r.Id);return new {trackId=t.Id,regionId=r.Id};
   case "transport":string action=Convert.ToString(args["action"]);if(action=="play"){if(args.ContainsKey("beat"))SetCursorBeat(Arg(args,"beat",0));if(!_engine.Playing)StartTransport();}else if(action=="stop"||action=="pause")StopAudio();else if(action=="seek")SetCursorBeat(Arg(args,"beat",0));else throw new ArgumentException("action must be play, stop, pause or seek.");return new {playing=_engine.Playing,beat=_engine.PositionBeat};
   case "set_tempo":double tempo=Arg(args,"bpm",120);if(tempo<20||tempo>400)throw new ArgumentOutOfRangeException("bpm");SetTempo(tempo);return new {tempo=_project.Tempo};
   case "set_track_mix":var mix=FindTrack(Guid.Parse(Convert.ToString(args["trackId"])));if(mix==null)throw new InvalidOperationException("Track unavailable.");var after=new Track{GainDb=Arg(args,"gainDb",mix.GainDb),Pan=Arg(args,"pan",mix.Pan),Muted=args.ContainsKey("mute")?Convert.ToBoolean(args["mute"]):mix.Muted,Solo=args.ContainsKey("solo")?Convert.ToBoolean(args["solo"]):mix.Solo};_history.Execute(_project,new SetTrackMixCommand(mix.Id,mix,after));if(args.ContainsKey("arm"))_history.Execute(_project,new SetTrackArmCommand(mix,Convert.ToBoolean(args["arm"])));RefreshState();return new {trackId=mix.Id};
   case "save_project":string path=Path.GetFullPath(Convert.ToString(args["path"]));_engine.CapturePluginStates();ProjectFile.SaveAtomic(_project,path);_projectPath=path;_history.MarkSaved();RefreshState();return new {path=path};
   case "open_project":if(_history.IsDirty)throw new InvalidOperationException("Save current changes before opening a project.");string open=Path.GetFullPath(Convert.ToString(args["path"]));var loaded=ProjectFile.Load(open);StopAudio();_engine.ResetProject();_project=loaded;_projectPath=open;_history.Reset(true);_selectedTrackId=_project.Tracks.Count>0?(Guid?)_project.Tracks[0].Id:null;_selectedRegionId=null;RefreshState();return new {path=open};
   case "export_audio":_engine.CapturePluginStates();string output=Path.GetFullPath(Convert.ToString(args["path"]));var options=new AudioExportOptions{StartBeat=Arg(args,"start",0),EndBeat=Arg(args,"end",16),SampleRate=(int)Arg(args,"sampleRate",48000),Bits=24};AudioExport.Render(_project,output,options,CancellationToken.None,null);return new {path=output};
   case "launch_cell":_engine.Launch(Guid.Parse(Convert.ToString(args["trackId"])),Guid.Parse(Convert.ToString(args["regionId"])),Arg(args,"quantum",4));if(!_engine.Playing)StartTransport();return new {queued=true};
   case "set_automation":var state=_project.Studio.Copy();Guid tid=Guid.Parse(Convert.ToString(args["trackId"]));string target=Convert.ToString(args["target"]);var lane=state.Automation.Find(a=>a.TrackId==tid&&a.Target==target);if(lane==null){lane=new AutomationLane{TrackId=tid,Target=target};state.Automation.Add(lane);}double beat=Arg(args,"beat",0);lane.Points.RemoveAll(p=>p.Beat==beat);lane.Points.Add(new AutomationPoint{Beat=beat,Value=Arg(args,"value",0)});lane.Points.Sort((a,b)=>a.Beat.CompareTo(b.Beat));CommitStudio("MCP automation",state);return new {points=lane.Points.Count};
   default:throw new InvalidOperationException("Unknown MCP tool: "+name);
   }
  }
  private WorkspaceWheelFilter _wheelFilter;
  private sealed class WorkspaceWheelFilter:IMessageFilter
  {
   private MainForm _owner;[DllImport("user32.dll")]private static extern IntPtr WindowFromPoint(Point point);[DllImport("imm32.dll")]private static extern uint ImmGetVirtualKey(IntPtr window);public WorkspaceWheelFilter(MainForm owner){_owner=owner;}
   public bool PreFilterMessage(ref Message message){if(_owner.IsDisposed)return false;if(message.Msg==0x100&&message.WParam.ToInt32()==0xE5&&Form.ActiveForm==_owner&&!_owner.IsTextEntryFocused()&&(_owner._softwareKeyboard==null||!_owner._softwareKeyboard.Visible)){var imeTarget=Control.FromChildHandle(message.HWnd);uint virtualKey=ImmGetVirtualKey(message.HWnd);if(imeTarget!=null&&imeTarget.FindForm()==_owner&&virtualKey>0&&virtualKey<256&&virtualKey!=0xE5){Keys imeKeys=(Keys)virtualKey|Control.ModifierKeys;return _owner.ProcessCmdKey(ref message,imeKeys);}}if(message.Msg!=0x20a&&message.Msg!=0x20e)return false;long coordinates=message.LParam.ToInt64();Point screen=new Point((short)(coordinates&65535),(short)((coordinates>>16)&65535));Control target=Control.FromChildHandle(WindowFromPoint(screen));if(target==null||target.FindForm()!=_owner){target=Control.FromChildHandle(message.HWnd);if(target==null||target.FindForm()!=_owner||!target.RectangleToScreen(target.ClientRectangle).Contains(screen))return false;}int delta=(short)((message.WParam.ToInt64()>>16)&0xffff);int buttons=(int)(message.WParam.ToInt64()&65535);if(message.Msg==0x20e)delta=-delta;Keys keys=Control.ModifierKeys&(Keys.Alt|Keys.Control|Keys.Shift);if(message.Msg==0x20e)keys|=Keys.Shift;if((buttons&8)!=0)keys|=Keys.Control;if((buttons&4)!=0)keys|=Keys.Shift;if((keys&(Keys.Control|Keys.Alt))==(Keys.Control|Keys.Alt)){_owner._settings.UiScale=Math.Max(60,Math.Min(200,_owner._settings.UiScale+(delta>0?1:-1)));_owner.RequestUiScale();return true;}for(Control c=target;c!=null;c=c.Parent){var timeline=c as TimelineEditor;if(timeline!=null){timeline.NavigateWheel(screen,delta,keys);return true;}var piano=c as PianoRollEditor;if(piano!=null){piano.NavigateWheel(screen,delta,keys);return true;}}return false;}
  }
  private static IEnumerable<Control> Descendants(Control root){foreach(Control child in root.Controls){yield return child;foreach(Control nested in Descendants(child))yield return nested;}}
  private sealed class NativeMetric{public Rectangle Bounds;public float Font;public Padding Padding,Margin;public List<float> Rows;public List<float> Columns;}
  private Dictionary<Control,NativeMetric> _nativeMetrics=new Dictionary<Control,NativeMetric>();
  private void ScaleNativePanel(Control root,float scale){
   foreach(Control c in new[]{root}.Concat(Descendants(root))){
    if(c is PianoRollEditor){((PianoRollEditor)c).ApplyScale();continue;}bool pianoChild=false;for(Control p=c.Parent;p!=null&&p!=root;p=p.Parent)if(p is PianoRollEditor){pianoChild=true;break;}if(pianoChild)continue;
    NativeMetric metric;if(!_nativeMetrics.TryGetValue(c,out metric)){metric=new NativeMetric{Bounds=c.Bounds,Font=c.Font.SizeInPoints,Padding=c.Padding,Margin=c.Margin};var table=c as TableLayoutPanel;if(table!=null){metric.Rows=new List<float>();foreach(RowStyle row in table.RowStyles)metric.Rows.Add(row.SizeType==SizeType.Absolute?row.Height:-1);metric.Columns=new List<float>();foreach(ColumnStyle col in table.ColumnStyles)metric.Columns.Add(col.SizeType==SizeType.Absolute?col.Width:-1);}_nativeMetrics[c]=metric;}
    bool canvas=c is ScaledCanvas;
    if(!canvas&&c.Font.SizeInPoints!=metric.Font*scale)c.Font=new Font(c.Font.FontFamily,metric.Font*scale,c.Font.Style);
    if(c.Dock==DockStyle.Top||c.Dock==DockStyle.Bottom)c.Height=Math.Max(1,(int)(metric.Bounds.Height*DisplayScale.For(root)));
    else if(c.Dock==DockStyle.Left||c.Dock==DockStyle.Right)c.Width=Math.Max(1,(int)(metric.Bounds.Width*DisplayScale.For(root)));
    else if(c.Dock==DockStyle.None&&c!=root)c.Bounds=new Rectangle((int)(metric.Bounds.X*DisplayScale.For(root)),(int)(metric.Bounds.Y*DisplayScale.For(root)),Math.Max(1,(int)(metric.Bounds.Width*DisplayScale.For(root))),Math.Max(1,(int)(metric.Bounds.Height*DisplayScale.For(root))));
    var layout=c as TableLayoutPanel;if(layout!=null&&metric.Rows!=null){for(int i=0;i<Math.Min(metric.Rows.Count,layout.RowStyles.Count);i++)if(metric.Rows[i]>=0)layout.RowStyles[i].Height=metric.Rows[i]*DisplayScale.For(root);for(int i=0;i<Math.Min(metric.Columns.Count,layout.ColumnStyles.Count);i++)if(metric.Columns[i]>=0)layout.ColumnStyles[i].Width=metric.Columns[i]*DisplayScale.For(root);}
   }root.PerformLayout();
  }
  private void ApplyAdvancedScale(){DisplayScale.User=_settings.UiScale/100f;ScaleNativePanel(_browser,DisplayScale.User);ScaleNativePanel(_inspector,DisplayScale.User);ScaleNativePanel(_arrangementToolbar,DisplayScale.User);ScaleNativePanel(_lowerDock,DisplayScale.User);float scale=DisplayScale.For(this);_launcher.CellWidth=88;_launcher.RowHeight=54;_launcher.HeaderWidth=205;_launcher.Invalidate();_mixer.SetScale(scale);_inspector.AdaptHeight(scale);foreach(Control child in Descendants(this))if(child is ScaledCanvas)child.Invalidate();var shell=_mediaSplit.Parent as TableLayoutPanel;if(shell!=null){shell.RowStyles[0].Height=21*scale;shell.RowStyles[1].Height=56*scale;shell.RowStyles[3].Height=23*scale;}}
 }
